// ========================================
// 🔍 كشف طلب العنصر البشري
// Human Request Detection (Arabic + English)
// ========================================

const body = $input.first().json.body || $input.first().json;
const message = (body.message || body.text || body.Body || '').toString().trim();
const customerName = body.customerName || body.ProfileName || body.name || 'العميل';
const customerPhone = body.phone || body.From || body.from || '';
const conversationId = body.conversationId || body.chatId || '';
const channelType = body.channelType || body.channel || 'whatsapp';

// Arabic + English patterns for human agent request
const humanPatterns = [
  /خدم[ةه]\s*العملا[ءإ]/,
  /عنصر\s*بشر[يى]/,
  /موظف/,
  /بشر[يى]/,
  /إنسان|انسان/,
  /شخص\s*(حقيقي)?/,
  /آدمي|ادمي/,
  /حولن[يى]/,
  /أبغ[يى]\s*(أ)?كلم/,
  /ابغ[يى]\s*(ا)?كلم/,
  /عايز\s*(أ)?كلم/,
  /عاوز\s*(أ)?كلم/,
  /بدي\s*احك[يى]/,
  /تحدث\s*مع/,
  /محادث[ةه]\s*بشر/,
  /اتصال\s*بشر/,
  /كلمني\s*حد/,
  /ابي\s*احد/,
  /\bhuman\b/i,
  /\bagent\b/i,
  /\brepresentative\b/i,
  /\bsupport\s*team\b/i,
  /\breal\s*person\b/i
];

const humanRequested = humanPatterns.some(p => p.test(message));

// Detect if message contains an order number (e.g. #12345 or 12345)
const orderMatch = message.match(/#?(\d{4,10})/);
const hasOrderNumber = !!orderMatch;
const orderNumber = orderMatch ? orderMatch[1] : null;

return [{
  json: {
    message,
    customerName,
    customerPhone,
    conversationId,
    channelType,
    humanRequested,
    hasOrderNumber,
    orderNumber,
    timestamp: new Date().toISOString()
  }
}];

// ========================================
// 🛑 إيقاف AI + إعداد رد التحويل للعنصر البشري
// ========================================

const data = $input.first().json;

const humanHandoffReply = `أهلاً بك ${data.customerName} 👋\n\nتم استلام طلبك وسيتواصل معك أحد أعضاء فريقنا في أقرب وقت ممكن.\n\nنقدّر صبرك ونشكرك على تواصلك معنا 🙏`;

const internalNote = `🚨 تنبيه: طلب عنصر بشري\n━━━━━━━━━━━━━━━━━\n👤 العميل: ${data.customerName}\n📱 الرقم: ${data.customerPhone}\n💬 الرسالة: ${data.message}\n⏰ الوقت: ${data.timestamp}\n\n📋 الإجراء المطلوب:\nالتواصل مع العميل فوراً والرد على استفساره.`;

return [{
  json: {
    ...data,
    aiStopped: true,
    replyToCustomer: humanHandoffReply,
    internalNote: internalNote,
    action: 'human_handoff'
  }
}];

// ========================================
// 📦 تجهيز بيانات الطلب من سلة
// ========================================

const prev = $('🔍 كشف طلب بشري + تحليل الرسالة').first().json;
const sallaResponse = $input.first().json;

let orderContext = '';

if (sallaResponse && sallaResponse.data) {
  const order = sallaResponse.data;
  const statusMap = {
    'created': 'تم الإنشاء',
    'pending': 'قيد المعالجة',
    'processing': 'جاري التجهيز',
    'completed': 'مكتمل',
    'shipped': 'تم الشحن',
    'delivered': 'تم التوصيل',
    'cancelled': 'ملغي',
    'refunded': 'مسترجع'
  };
  const status = statusMap[order.status?.slug] || order.status?.name || order.status?.slug || 'غير معروف';
  const items = (order.items || []).map(i => `• ${i.name} (الكمية: ${i.quantity})`).join('\n');
  const total = order.amounts?.total?.amount || order.total || 'غير محدد';
  const currency = order.amounts?.total?.currency || order.currency || 'SAR';
  const shipping = order.shipping?.company || 'غير محدد';
  const tracking = order.shipping?.tracking_link || '';

  orderContext = `\n=== بيانات الطلب #${prev.orderNumber} ===\nالحالة: ${status}\nالمنتجات:\n${items}\nالإجمالي: ${total} ${currency}\nشركة الشحن: ${shipping}${tracking ? '\nرابط التتبع: ' + tracking : ''}\n===========================\n`;
} else {
  orderContext = `\n[ملاحظة: لم يتم العثور على الطلب #${prev.orderNumber} في سلة]\n`;
}

return [{
  json: {
    ...prev,
    orderContext
  }
}];

// ========================================
// تمرير بدون بيانات طلب
// ========================================

const prev = $('🔍 كشف طلب بشري + تحليل الرسالة').first().json;

return [{
  json: {
    ...prev,
    orderContext: ''
  }
}];

