// ========================================
// 🧠 تحليل نتيجة AI Supervisor
// ========================================

const prev = $('🔀 دمج المسارات').first().json;
const supervisorRaw = $input.first().json;

let analysis = {
  sentiment: 'neutral',
  humanRequested: false,
  shouldEscalate: false,
  escalationReason: null,
  purchaseIntent: 'none',
  suggestedAction: 'رد طبيعي',
  suggestedInternalNote: null,
  confidence: 0.5
};

try {
  const content = supervisorRaw?.choices?.[0]?.message?.content || '{}';
  const parsed = JSON.parse(content);
  analysis = { ...analysis, ...parsed };
} catch (e) {
  // Supervisor parse failed, use defaults
}

// Business Rules: Escalation Gate
const needsEscalation = (
  analysis.confidence >= 0.70 &&
  (analysis.humanRequested === true ||
   analysis.sentiment === 'angry' ||
   analysis.shouldEscalate === true)
);

return [{
  json: {
    ...prev,
    supervisor: analysis,
    needsEscalation,
    action: needsEscalation ? 'escalate' : 'ai_reply'
  }
}];

// ========================================
// 🚨 تجهيز تنبيه التصعيد الداخلي
// ========================================

const data = $input.first().json;
const sv = data.supervisor;

const sentimentEmoji = {
  'positive': '😊',
  'neutral': '😐',
  'frustrated': '😤',
  'angry': '😡'
};

const escalationReply = `أهلاً ${data.customerName} 👋\n\nنقدّر تواصلك معنا ونتفهم موقفك تماماً. تم تحويل محادثتك لأحد أعضاء فريقنا المتخصصين وسيتواصل معك في أقرب وقت.\n\nنعتذر عن أي إزعاج ونشكرك على صبرك 🙏`;

const internalNote = `🚨 تنبيه تصعيد ذكي - AI Supervisor\n━━━━━━━━━━━━━━━━━━━━━━━━━━━\n${sentimentEmoji[sv.sentiment] || '😐'} شعور العميل: ${sv.sentiment}\n📋 سبب التصعيد: ${sv.escalationReason || 'تم الكشف تلقائياً'}\n🎯 نية الشراء: ${sv.purchaseIntent}\n💡 الإجراء المقترح: ${sv.suggestedAction}\n${sv.suggestedInternalNote ? '📝 ملاحظة: ' + sv.suggestedInternalNote : ''}\n━━━━━━━━━━━━━━━━━━━━━━━━━━━\n👤 العميل: ${data.customerName}\n📱 الرقم: ${data.customerPhone}\n💬 الرسالة الأصلية: ${data.message}\n⏰ الوقت: ${data.timestamp}\n🔒 الثقة: ${(sv.confidence * 100).toFixed(0)}%`;

return [{
  json: {
    ...data,
    aiStopped: true,
    replyToCustomer: escalationReply,
    internalNote: internalNote,
    action: 'escalation'
  }
}];

