// ========================================
// ✅ تجهيز الرد النهائي من الذكاء الاصطناعي
// ========================================

const prev = $('📊 تحليل نتيجة المشرف الذكي').first().json;
const aiResponse = $input.first().json;

let reply = 'عذراً، لم أتمكن من معالجة طلبك الآن. يرجى المحاولة مرة أخرى أو التواصل مع فريق الدعم.';

try {
  reply = aiResponse?.choices?.[0]?.message?.content || reply;
} catch (e) {
  // Use fallback reply
}

// ===== بوابة الأمان: منع تسريب ملاحظات داخلية =====
const dangerPatterns = [
  /AI Supervisor/i,
  /تنبيه تصعيد/,
  /ملاحظة داخلية/,
  /التوجيه للموظف/,
  /internal note/i,
  /🚨.*تنبيه/,
  /شعور العميل.*غاضب/,
  /سبب التصعيد/
];

const isUnsafe = dangerPatterns.some(p => p.test(reply));

if (isUnsafe) {
  reply = `أهلاً ${prev.customerName} 👋\nشكراً لتواصلك معنا! سيتم مراجعة استفسارك والرد عليك في أقرب وقت من فريقنا المتخصص.`;
}

return [{
  json: {
    ...prev,
    aiStopped: false,
    replyToCustomer: reply,
    internalNote: null,
    action: 'ai_reply',
    supervisorSummary: `${prev.supervisor?.sentiment || 'neutral'} | نية الشراء: ${prev.supervisor?.purchaseIntent || 'none'} | الثقة: ${((prev.supervisor?.confidence || 0) * 100).toFixed(0)}%`
  }
}];
